//! Product copy for the seven languages Vibex added beside English and Chinese.
//!
//! The three shipped languages keep their own static tables in each client;
//! these rows are keyed by the English sentence every call site already spells
//! out, so a client can translate a message it is about to draw without
//! changing how that message is written where it is drawn.
//!
//! A key with no row falls back to the caller's English text: showing English
//! is the documented fallback for an untranslated string, never a panic or an
//! empty label.

use crate::locale::Locale;

/// One translated sentence: the English source and the seven added languages.
#[derive(Debug, Clone, Copy)]
pub struct CopyRow {
    pub en: &'static str,
    pub ja: &'static str,
    pub ko: &'static str,
    pub de: &'static str,
    pub fr: &'static str,
    pub es: &'static str,
    pub pt_br: &'static str,
    pub ru: &'static str,
}

impl CopyRow {
    /// The row in `locale`, or its English source for a language this table
    /// does not carry (English and the two Chinese variants).
    pub const fn get(&self, locale: Locale) -> &'static str {
        match locale {
            Locale::Ja => self.ja,
            Locale::Ko => self.ko,
            Locale::De => self.de,
            Locale::Fr => self.fr,
            Locale::Es => self.es,
            Locale::PtBr => self.pt_br,
            Locale::Ru => self.ru,
            _ => self.en,
        }
    }
}

