/// The row for `en`, if this table carries it.
pub fn row_for(en: &str) -> Option<&'static CopyRow> {
    COPY_ROWS
        .binary_search_by(|row| row.en.cmp(en))
        .ok()
        .map(|index| &COPY_ROWS[index])
}

/// `en` in `locale`, or `en` itself when the table has no row or the locale
/// is one whose copy lives in the caller's own table.
pub fn localized(locale: Locale, en: &'static str) -> &'static str {
    match locale {
        Locale::En | Locale::ZhCn | Locale::ZhTw => en,
        other => row_for(en).map_or(en, |row| row.get(other)),
    }
}

/// `en` in `locale` with its named placeholders replaced from `args`.
///
/// A translated sentence cannot be passed to `format!`, so its placeholders
/// are filled by name instead. Callers pass the same names the English
/// sentence uses, which is what keeps a row and its call site in step.
pub fn fill(locale: Locale, en: &'static str, args: &[(&str, String)]) -> String {
    let mut value = localized(locale, en).to_string();
    for (name, replacement) in args {
        value = value.replace(&format!("{{{name}}}"), replacement);
    }
    value
}
